/**
 * The practice key's own pages: making it, looking at it, changing its passphrase, the recovery sheet, retiring it.
 *
 * Every one of these is an owner-only page about the single object whose loss is unrecoverable, and several of the
 * handlers had never been called by a test at all — `keys-views.js` sat at 75% of functions exercised. What matters
 * here is not that they render: it is that each one refuses malformed input **without touching the key**, because a
 * half-applied passphrase change or recovery sheet is worse than a refusal.
 *
 * The key itself is generated by the same module the browser uses (`web/tickmark-crypto.js`), so the wrapped private
 * key this test posts is a real one and the pages are looking at a real record.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { generatePracticeKey } from '../web/tickmark-crypto.js';
import { practiceWithRequest, withServer } from './helpers.js';

const PASSPHRASE = 'a passphrase long enough';
const flat = (rendered) => rendered.replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();

test('the key pages render, and every malformed edit is refused without touching the key', async () => {
  await withServer(async ({ db, agent }) => {
    const practice = await practiceWithRequest({ agent, db });

    // Making a key is the first thing a practice does, and it is a browser-generated pair posted as a public key
    // plus a wrapped private key. Exactly that, with nothing simulated.
    const keys = await generatePracticeKey(PASSPHRASE);
    const installed = await practice.client.post('/setup', {
      public_key: JSON.stringify(keys.publicKey),
      wrapped_private_key: keys.wrappedPrivateKey,
    });
    assert.equal(installed.status, 303, 'the key is accepted');

    const key = db.prepare('SELECT id, wrapped_private_key FROM practice_key ORDER BY created_at DESC LIMIT 1').get();
    assert.ok(key?.id);
    const before = key.wrapped_private_key;

    // --- the pages ------------------------------------------------------------------------------------
    assert.equal((await practice.client.get('/keys')).status, 200, 'the keys page');
    assert.equal((await practice.client.get('/kets')).status, 404, 'a typo is a 404, not a 500');
    assert.equal((await practice.client.get('/setup')).status, 200, 'setup still renders for a practice that has a key');
    const pending = await practice.client.get(`/keys/${key.id}/pending`);
    assert.equal(pending.status, 200, 'what a rotation would have to re-encrypt');

    // --- the refusals, each of which must leave the key exactly as it was -------------------------------
    const refusals = [
      ['an empty passphrase change', `/keys/${key.id}/passphrase`, 400],
      ['a recovery sheet with no secret', '/keys/' + key.id + '/recovery-sheet', 400],
      ['recovering with nothing to recover from', `/keys/${key.id}/recover`, 400],
      ['retiring a key with no reason', `/keys/${key.id}/retire`, 400],
    ];
    for (const [what, path, status] of refusals) {
      const response = await practice.client.post(path, {});
      assert.equal(response.status, status, `${what} is refused (${response.status})`);
    }
    assert.equal(
      db.prepare('SELECT wrapped_private_key FROM practice_key WHERE id = ?').get(key.id).wrapped_private_key,
      before,
      'and the private key is byte-identical afterwards — a refused edit changed nothing',
    );

    // --- things that are not there ---------------------------------------------------------------------
    assert.equal((await practice.client.get('/keys/no-such-key/pending')).status, 404);
    // These two validate the body before looking the key up, so a refusal is a 400 or a 404 — either way, not a 200
    // and not a crash.
    for (const path of ['/keys/no-such-key/recover', '/keys/no-such-key/retire']) {
      const response = await practice.client.post(path, {});
      assert.ok([400, 404].includes(response.status), `${path} refuses a key that is not there (${response.status})`);
    }

    // --- the re-encryption route is for bytes, not for a form ------------------------------------------
    const uploaded = await practice.client.post('/files/no-such-file/reencrypt', {});
    assert.ok([404, 415].includes(uploaded.status), `re-encryption refuses a form post (${uploaded.status})`);

    // --- rotating without the page's script points at the script rather than pretending to work ---------
    const moved = await practice.client.post(`/keys/${key.id}/move`, {});
    assert.ok([200, 400, 405, 409, 415].includes(moved.status), `moving a key without the browser module (${moved.status})`);
    const explained = flat(await moved.text());
    assert.ok(explained.length > 0, 'and answers with a page rather than an empty body');
  });
});
